return items.map(item => {
  return {
    customerName: item.json.billing.first_name + ' ' + item.json.billing.last_name,
    phoneNumber: item.json.billing.phone.replace(/\D/g, ''),
    email: item.json.billing.email,
    address: item.json.billing.address_1,
    products: item.json.line_items.map(product => ({
      title: product.name,
      id: product.product_id,
      quantity: product.quantity,
      price: product.total
    })),
    invoiceLink: item.json.invoice_url
  };
});

return items.map(item => {
  item.json.phoneNumber = item.json.phoneNumber.replace(/\D/g, '');
  return item;
});
